{
  "case_id": "xsu_sg_014_occupational_injury_opinion",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret fastslår fejlagtigt, at Udbetaling Danmark er bundet af AES's udtalelse, når den er afgivet efter en 'saglig og mønstret vurdering'. Kilden siger, at udtalelsen kun er vejledende og ikke bindende. Svaret omtaler desuden erhvervsskade og varig formindskning af arbejdsevnen, som ikke fremgår af kilderne, og udelader studiejob-vurderingen."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Svaret nævner hverken, hvor meget funktionsnedsættelsen påvirker evnen til at arbejde, eller om funktionsevnen er så nedsat, at et studiejob ikke kan varetages. Det handler i stedet om erhvervsrelateret skade og varig formindskning af arbejdsevnen."},
    "c03_direct_relevance": {"label": "not_met", "reason": "Svaret forsøger at behandle begge dele af spørgsmålet, men indholdet af udtalelsen er forkert, og bindingsspørgsmålet besvares forkert. Det er derfor ikke et reelt svar på de væsentlige dele."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledning."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet, så støtten til påstandene kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer uunderstøttede regler: at udtalelsen binder Udbetaling Danmark, kravet om en 'saglig og mønstret vurdering', at tvivl om gyldighed giver adgang til selvstændig vurdering, og at skaden skal være erhvervsrelateret. Intet af dette findes i materialet."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Den påkrævede kvalifikation, at udtalelsen er vejledende og ikke bindende for Udbetaling Danmark, mangler og er erstattet af det modsatte. Svaret nævner heller ikke, at udtalelsen bygger på sagens dokumenter uden undersøgelse."},
    "c09_reasoning_coherence": {"label": "not_met", "reason": "Svaret er internt usammenhængende. Det siger, at Udbetaling Danmark er bundet, men at myndigheden alligevel kan foretage en selvstændig vurdering, hvis udtalelsen er mangelfuld. Det er tæt på at underminere sin egen bindingskonklusion."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Svaret gør en vejledende, ikke-bindende udtalelse til noget bindende ('er bundet', 'skal tage til følge'). Det forvrænger kildens modalitet."}
  },
  "xhaile_coverage": {
    "A68": {"label": "no", "reason": "Svaret dækker ikke de to vurderingspunkter (påvirkning af evnen til at arbejde og studiejob), nævner ikke, at udtalelsen er vejledende, bygger på sagens dokumentation og ikke kræver undersøgelse, og angiver ikke, at Udbetaling Danmark kan anmode om den. Det angiver også den forkerte bindingsvirkning."}
  },
  "overall_notes": "Svaret indeholder en væsentlig juridisk fejl, idet det hævder, at Udbetaling Danmark er bundet af AES's udtalelse. Kilden siger det modsatte. De kritiske elementer om arbejdsevne og studiejob mangler, og der er ingen kildeangivelse."
}

